(async () => {
  const TAG = "🧪 Contagion";
  const mode = args[0];
  const last = args.at(-1) || {};
  const token = canvas.tokens.get(last.tokenId);
  const actor = token?.actor;
  const origin = last.origin;
  if (!actor || !origin) return console.warn(TAG, "找不到 actor 或 origin");

  const aeDoc = await fromUuid(origin);
  const parentItem = aeDoc?.parent;
  const caster = parentItem?.actor ?? null;
  const spellDC = Number(caster?.getRollData?.()?.attributes?.spelldc) ||
                  Number(parentItem?.system?.save?.dc) || null;

  console.log(TAG, "mode:", mode, "target:", actor.name, "caster:", caster?.name, "spellDC:", spellDC);

  const safeKey = origin.replace(/[^\w]/g, "_");
  const ns = "world", rootKey = "contagion";

  function getRoot() {
    return actor.getFlag(ns, rootKey) || {};
  }
  function getBag() {
    return getRoot()[safeKey] || {};
  }
  async function setBag(bag) {
    const root = foundry.utils.duplicate(getRoot());
    root[safeKey] = bag;
    await actor.setFlag(ns, rootKey, root);
  }
  async function deleteBag() {
    const root = foundry.utils.duplicate(getRoot());
    delete root[safeKey];
    await actor.setFlag(ns, rootKey, root);
  }
  function findContagionEffect() {
    return actor.effects.find(e => e.origin === origin && /Contagion|疫病术/i.test(e.label));
  }

  if (mode === "on") {
    if (spellDC == null) {
      ui.notifications.warn("无法获取施法 DC，宏中止"); return;
    }
    await setBag({ succ: 0, fail: 0, dc: spellDC, _hookId: null });

    const hookId = Hooks.on("updateCombat", async (combat, changed) => {
      if (changed.turn === undefined && changed.round === undefined) return;
      const turns = combat.turns;
      if (!turns?.length) return;
      const prevIdx = (combat.turn - 1 + turns.length) % turns.length;
      const prev = turns[prevIdx];
      const prevActorId = prev.actorId ?? prev.actor?.id;
      const prevTokenId = prev.tokenId ?? prev.token?.id;
      if (prevActorId !== actor.id && prevTokenId !== token.id) return;
      if (!findContagionEffect()) return console.log(TAG, "Contagion 已移除");

      const bag = getBag();
      const roll = await actor.rollAbilitySave("con", { flavor: `Contagion Save DC ${bag.dc}` });
      const passed = roll.total >= bag.dc;
      passed ? bag.succ++ : bag.fail++;
      await setBag(bag);

      ChatMessage.create({
        content: `<div class="chat-card"><header><h3>Contagion Save</h3></header>
                  <div class="card-content">
                    <p>${actor.name}: ${roll.total} vs DC ${bag.dc} → ${passed ? "成功" : "失败"}</p>
                    <p>成功 ${bag.succ} / 失败 ${bag.fail}</p>
                  </div></div>`,
        speaker: ChatMessage.getSpeaker({ actor })
      });
      console.log(TAG, `Save ${roll.total} → ${passed ? "OK" : "Fail"} | succ=${bag.succ} fail=${bag.fail}`);

      if (bag.succ >= 3) {
        console.log(TAG, "三次成功，移除 Contagion");
        const eff = findContagionEffect();
        if (eff) await actor.deleteEmbeddedDocuments("ActiveEffect", [eff.id]);
        Hooks.off("updateCombat", hookId);
        await deleteBag();
        return;
      }
      if (bag.fail >= 3) {
        console.log(TAG, "三次失败，弹窗选择疾病");
        Hooks.off("updateCombat", hookId);

        const options = [
          "失明症 Blinding Sickness",
          "腐热症 Filth Fever",
          "烂肉症 Flesh Rot",
          "脑热症 Mindfire",
          "癫痫症 Seizure",
          "恶心症 Slimy Doom"
        ];
        const chosen = await new Promise(r => {
          new Dialog({
            title: "请选择疾病类型",
            content: `<form><div class="form-group"><label>疾病</label>
              <select id="disease">${options.map(o => `<option>${o}</option>`).join("")}</select></div></form>`,
            buttons: { ok: { label: "确定", callback: html => r(html[0].querySelector("#disease").value) },
                       cancel: { label: "取消", callback: () => r(null) } },
            default: "ok"
          }).render(true);
        });

        if (!chosen) {
          ui.notifications.warn("取消。");
          await deleteBag(); return;
        }
        console.log(TAG, "选病:", chosen);

        const poisonE = actor.effects.filter(e => /poisoned|中毒/i.test(e.label));
        if (poisonE.length) await actor.deleteEmbeddedDocuments("ActiveEffect", poisonE.map(e => e.id));

        const srcEffect = parentItem.effects.find(e => e.label === chosen);
        if (!srcEffect) ui.notifications.warn(`找不到效果：${chosen}`);
        else {
          const data = srcEffect.toObject();
          delete data._id; data.origin = origin;
          data.flags = data.flags || {}; data.flags.dae = data.flags.dae || {};
          data.flags.dae.stackable = "noneName";
          await actor.createEmbeddedDocuments("ActiveEffect", [data]);
          console.log(TAG, `施加疾病：${chosen}`);
        }

        const eff = findContagionEffect();
        if (eff) await actor.deleteEmbeddedDocuments("ActiveEffect", [eff.id]);
        await deleteBag();
        return;
      }
    });

    bag._hookId = hookId;
    await setBag(bag);
    console.log(TAG, "注册 hook:", hookId);
    return;
  }

  if (mode === "off") {
    const bag = getBag();
    if (bag._hookId) Hooks.off("updateCombat", bag._hookId);
    await deleteBag();
    console.log(TAG, "解绑并清理");
    return;
  }
})();
